//#WCCChallenge
let img;
let x1, y1, imgX, imgY;
let mouseIsDown;
let backColour;

function setup() {
  createCanvas(windowWidth, windowHeight);
	imageMode(CENTER);
	pixelDensity(1);
	colorMode(HSB, 360, 1, 1, 1);

	imgX = width/2;
	imgY = height/2;
	img = createGraphics(2000, 2000);
  img.colorMode(HSB, 360, 1, 1, 1);
  img.translate(img.width/2, img.height/2);

	generateImage();
}

function draw() {
	background(backColour);
  image(img, imgX, imgY);

	if(mouseIsDown){

		imgX += (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - x1;
		imgY += (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - y1;

		x1 = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
		y1 = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

	}
}

function mousePressed(){
	mouseIsDown = true;

	x1 = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	y1 = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}

function mouseReleased(){
	mouseIsDown = false;
}

function keyPressed(){

	if(key == ' '){
		generateImage();
	}

}

function generateImage(){
	backColour = color(random(180, 270), 1, 0.1);
	img.background(backColour);
	img.fill(0, 0, 1);
	img.circle(0, 0, 100);
  branch(5, TWO_PI, random(360), 90, 0.2);
}

function branch(count, theta, Hue, hueRange, Saturation){

  if(count < 1) return;

  for(let i = 0; i < 9; i++){

    img.push();

    img.rotate(random(theta));

    img.fill(Hue, Saturation, 1);
    img.stroke(Hue, Saturation, 1, 0.1);

		let dist = count * random(30, 70);
    img.line(0, 0, dist, 0);
    img.translate(dist, 0);

    img.circle(0, 0, pow(count, 2));
    let newHue = Hue + random(-hueRange, hueRange);

    if(newHue > 360) newHue -= 360;
    else if(newHue < 0) newHue += 360;

    branch(count-1, theta*0.3, newHue, hueRange*0.75, Saturation+0.15);

    img.pop();

  }

}
